-- Demo data for Torneo Trives 2026.
-- Teams are loaded without players for now; match events stay team-level.
-- Execute this in the Supabase SQL Editor after the initial schema.
--
-- Format:
-- 12 teams, 4 groups of 3 teams.
-- The top 2 teams in each group qualify for quarter finals.
--
-- Group tiebreak criteria:
-- 1. Head-to-head result.
-- 2. Penalties, if a specific tiebreaker shootout is played.
-- 3. Goal difference.
-- 4. Cards.

begin;

alter table public.matches
  add column if not exists home_penalty_score integer,
  add column if not exists away_penalty_score integer,
  add column if not exists tiebreak_note text;

delete from public.matches
where tournament_id in (
  select id
  from public.tournaments
  where slug = 'torneo-trives-2026'
);

delete from public.tournaments
where slug = 'torneo-trives-2026';

delete from public.players
where team_id between '20260000-0000-4000-8000-000000000101' and '20260000-0000-4000-8000-000000000112';

values (
  '20260000-0000-4000-8000-000000000001',
  'Torneo Trives 2026',
  'torneo-trives-2026',
  'active'
);



on conflict (id) do update set name = excluded.name, updated_at = now();

select '20260000-0000-4000-8000-000000000001', id
from public.teams
where id between '20260000-0000-4000-8000-000000000101' and '20260000-0000-4000-8000-000000000112'
on conflict (tournament_id, team_id) do nothing;

on conflict (group_id, team_id) do nothing;


  id, tournament_id, stage_id, group_id, home_team_id, away_team_id,
  scheduled_at, home_score, away_score, status, round_label,
  home_penalty_score, away_penalty_score, tiebreak_note
)
